pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post_res = post_residual as f64;

    // Base score: prioritize Best Fit (minimize post_residual)
    // We add a penalty for "near-empty" bins to discourage fragmentation
    let mut score = post_res.powf(1.5);

    // Lookahead logic: if we can fit the next item in the current residual, reward it.
    // If the next item is large, avoid leaving a tiny, unusable residual (the "death trap").
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= (next_item_size as f64).powf(1.2);
        } else if post_residual > 0 && post_residual < 15 {
            // Penalty for creating a "sliver" that likely won't fit future items
            score += 20.0 * (1.0 - progress);
        }
    }

    // Heuristic for opening new bins:
    // If this is the new-bin candidate (bin_residual == bin_capacity),
    // we return a score that reflects the cost of opening a new bin vs filling existing ones.
    if bin_residual == bin_capacity {
        // Only open a new bin if the mean residual of existing bins is already very low,
        // or if we are forced to (fitting_bins_count == 0).
        let penalty = if fitting_bins_count == 0 {
            0.0
        } else {
            // Non-linear cost to open a new bin based on how much space we are wasting in others
            (mean_residual * 0.5) + (progress * 30.0)
        };
        score = 25.0 + penalty;
    } else {
        // For existing bins, favor bins that are already "tight" (low mean_residual)
        // to keep the bin packing density high.
        score -= (bin_capacity as f64 - mean_residual) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: We prefer smaller post-residuals (Best Fit).
    let mut score = post_residual as f64;

    // Penalty for opening a new bin:
    // Only open a new bin if the current fit is extremely poor (post_residual is large).
    if is_new_bin {
        if open_bins_count == 0 {
            return 0.0;
        }
        // Penalize opening a new bin based on the scarcity of current fit options.
        // We only open if the average residual is already quite low, implying we are "tight".
        score = 25.0 + (mean_residual * 0.5) + (progress * 10.0);
    } else {
        // Lookahead heuristic: If the next item exists, favor bins that leave space for it.
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                // Perfect: This bin can accommodate the next item.
                score -= 15.0;
            } else if post_residual > 0 && post_residual < 10 {
                // Terrible: This bin creates a "sliver" that likely cannot fit anything.
                score += 20.0;
            }
        }

        // If this is the last chance for this item, reduce penalty to prevent unnecessary new bin creation.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }

        // Global state correction: If we have many open bins, penalize leaving space.
        score += (open_bins_count as f64 * 0.2);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Penalty for creating a bin that is too small to fit future expected items
    // We use the next_item_size as a proxy for immediate demand.
    let fit_penalty = if post < next_item_size as f64 && next_item_size > 0 {
        (next_item_size as f64 - post) * 2.5
    } else {
        0.0
    };

    // Reward bins that have residuals close to the mean, promoting compaction
    let compaction_reward = (post - mean_residual).abs() * 0.5;

    // Non-linear coupling: As the stream progresses, we become more conservative about 
    // opening new bins (increasing the cost of new bins relative to existing ones).
    let is_new_bin = bin_residual == bin_capacity;
    let base_score = if is_new_bin {
        // New bins are penalized heavily as we approach the end of the stream
        35.0 + (progress * 45.0)
    } else {
        // Existing bins: prefer tighter fits (lower post_residual)
        post + fit_penalty + compaction_reward
    };

    // Edge case: If this is the only bin that fits, prioritize it strongly
    let availability_bonus = if fitting_bins_count == 1 && !is_new_bin {
        -20.0
    } else {
        0.0
    };

    base_score + availability_bonus
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Heuristic #91: Harmonic-Residual Balancing
    // We aim to minimize post_residual (Best Fit) while applying harmonic penalties 
    // for leaving "dead-space" that cannot accommodate the lookahead item.

    let mut score = post_residual as f64;

    // 1. Harmonic penalty for small residuals that are too small for the lookahead item.
    // If the next item cannot fit in this post_residual, it is "dead space".
    if next_item_size > 0 && post_residual < next_item_size {
        score += 50.0;

        // Non-linear penalty based on how far we are from fitting the next item.
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // 2. Penalty for opening a new bin (bin_residual == bin_capacity).
    // We only open a new bin if the current open bins result in very poor future packing.
    if bin_residual == bin_capacity {
        score += 35.0; 

        // If we are near the end of the stream, discourage opening new bins.
        let progress = step_index as f64 / total_items as f64;
        score += progress * 40.0;
    }

    // 3. Harmonic class alignment: favor residuals that are multiples of common item sizes (e.g., 20, 25).
    // If the residual is a "harmonic" value, it's more likely to fit future items.
    if post_residual % 20 == 0 {
        score -= 10.0;
    } else if post_residual % 25 == 0 {
        score -= 8.0;
    }

    // 4. Global state coupling: If many bins are open, be more conservative about 
    // opening new ones or creating highly fragmented bins.
    if open_bins_count > 5 {
        score += (open_bins_count as f64) * 2.0;
    }

    // 5. Lookahead efficiency: penalize if this placement leaves a residual
    // that is inefficient for the mean_residual of the system.
    let residual_diff = (post_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score is the residual space (Best Fit principle).
    // We want to minimize the post_residual to pack tightly.
    let mut score = post;

    // Penalty for leaving a 'dead' gap that is too small for any future item.
    // If post_residual is < 10, it is likely unusable for any incoming item.
    if post > 0.0 && post < 10.0 {
        score += 50.0 * (1.0 - (post / 10.0));
    }

    // Lookahead interaction: if the next item is large, favor bins that can accommodate it.
    // If post_residual is too small to fit the next item, penalize it.
    if next_item_size > 0 {
        if post < next_item_size as f64 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Dynamic thresholding: as the stream progresses, prioritize closing bins
    // to keep the number of open bins (open_bins_count) low.
    let open_penalty = (open_bins_count as f64) * (1.0 + progress);
    score += open_penalty;

    // Favor keeping the mean_residual stable to prevent fragmented bins.
    // If this bin's post_residual is significantly lower than the mean, it's a good fit.
    let dev_from_mean = (post - mean_residual).abs();
    score += 0.5 * dev_from_mean;

    // Special handling for the New Bin candidate (bin_residual == bin_capacity).
    // Only open a new bin if the current fit is extremely poor (post > 40).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score = 0.0; // Must open new bin
        } else {
            // Penalize opening a new bin heavily unless the fit is very poor.
            score = 60.0 + (progress * 20.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Current progress factor [0.0, 1.0]
    let progress = step_index as f64 / total_items as f64;

    // Base score: prioritize tighter fits (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating "dead zones": if the post_residual is too small to fit typical future items
    // but too large to be considered "full", we penalize it.
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead logic: if the next item is large, avoid leaving a residual that is just slightly too small
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Penalty for stranding a large item
            score += 15.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            // Reward for creating a state that can accommodate the next item
            score -= 10.0;
        }
    }

    // Global state awareness: 
    // If we have many open bins, we should be more aggressive in filling existing ones (Best Fit).
    // If we have few open bins, we can be more flexible.
    if open_bins_count > 5 {
        score -= (open_bins_count as f64) * 0.5;
    }

    // New Bin Logic:
    // If this is a new bin (bin_residual == bin_capacity), we only take it if 
    // current fitting bins are all "bad" (e.g., they leave very small, unusable residuals).
    if bin_residual == bin_capacity {
        // Only open a new bin if we are early in the stream or if existing bins are mostly full
        // and would result in fragmented space.
        if progress < 0.8 && mean_residual > 15.0 {
            score += 10.0; 
        } else {
            score += 40.0; // High penalty to prevent unnecessary new bins
        }
    }

    // Fitting Bins Count bias:
    // If only one bin fits, prioritize it heavily to avoid opening a new one unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    score
}

